WITH base AS (SELECT *, ROUND(quantity, 1) AS quantity_rounded FROM inventory WHERE quantity BETWEEN 194 AND 222), with_dims AS (SELECT e.*, p.product_name, p.stock_qty, p.price FROM base e LEFT JOIN products p ON e.product_id = p.id), enriched AS (SELECT s.*, d.stock_qty AS product_stock_qty, d.category, d.brand FROM with_dims s LEFT JOIN products d ON s.product_id = d.id), enriched_inventory AS (SELECT e.id, e.product_id, e.quantity, e.quantity_rounded, e.price, e.category, d.product_name AS product_product_name, d.price AS product_price FROM enriched e LEFT JOIN products d ON e.product_id = d.id), filtered AS (SELECT *, SUBSTRING(product_product_name, 1, 3) AS product_product_name_prefix, LEAST(price, quantity) AS least_price_quantity, COALESCE(category, 'DIRECT') AS resolved_category FROM enriched_inventory WHERE category IS NOT NULL) SELECT CASE WHEN price >= 940 THEN 'PREMIUM' ELSE 'STANDARD' END AS price_tier, ROUND(AVG(product_price), 2) AS avg_product_price, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, COUNT(*) FILTER (WHERE category = 'Fashion') AS fashion_rows FROM filtered GROUP BY CUBE (CASE WHEN price >= 940 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY avg_product_price DESC;
